import { useEffect, useState } from "react";
import { motion, useAnimate, useReducedMotion } from "motion/react";
import { ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
export default function NotFoundPagesSliced() {
    const [scope, animate] = useAnimate<HTMLButtonElement>();
    const [active, setActive] = useState(false);
    const reduce = useReducedMotion();
    useEffect(() => {
        const slices = scope.current?.querySelectorAll<HTMLSpanElement>("span");
        if (!slices)
            return;
        [...slices].forEach((slice, i) => {
            const distance = (i % 2 ? 1 : -1) * (18 + i * 4);
            if (active && !reduce) {
                for (const animation of slice.getAnimations()) {
                    if (animation.effect instanceof KeyframeEffect && animation.effect.getKeyframes().some(frame => "transform" in frame))
                        animation.cancel();
                }
            }
            return active && !reduce ? animate(slice, {
                transform: ["translate3d(0, 0, 0)", `translate3d(${distance}px, 0px, 0px)`, `translate3d(${-distance * 0.55}px, 0px, 0px)`, "translate3d(0, 0, 0)"],
            }, { duration: 1.5, delay: i * 0.035, ease: [0.77, 0, 0.18, 1], repeat: Infinity, repeatDelay: 0.15 })
                : animate(slice, { transform: "translate3d(0px, 0px, 0px)" }, { duration: 0.22, ease: [0.23, 1, 0.32, 1] });
        });
    }, [active, reduce, animate, scope]);
