          <span className="art:font-mono art:text-xs art:uppercase art:tracking-[0.18em] art:opacity-60">
            {"Page missing"}
          </span>
        </header>
        <div className="art:flex art:flex-1 art:flex-col art:items-center art:justify-center art:px-5 art:py-8 art:text-center">
          <motion.button ref={scope} onMouseEnter={() => setActive(true)} onMouseLeave={() => setActive(false)} onFocus={() => setActive(true)} onBlur={() => setActive(false)} {...press} type="button" className="art:items-center art:justify-center art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:gap-2 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:inline-block art:p-0 art:font-normal art:text-inherit art:hover:bg-transparent art:hover:text-inherit art:relative art:h-[34cqw] art:max-h-[350px] art:min-h-40 art:w-full art:cursor-default art:overflow-hidden art:rounded-full" aria-label="404. Hover to split the number." tabIndex={0}>
            <span aria-hidden="true" className="art:absolute art:inset-0 art:flex art:items-center art:justify-center art:font-semibold art:text-9xl art:leading-tight art:tracking-[-0.1em] art:text-foreground" style={{ clipPath: "inset(0% 0px 86%)" }}>
              {"404"}
            </span>
            <span aria-hidden="true" className="art:absolute art:inset-0 art:flex art:items-center art:justify-center art:font-semibold art:text-9xl art:leading-tight art:tracking-[-0.1em] art:text-foreground" style={{ clipPath: "inset(14% 0px 72%)" }}>
              {"404"}
            </span>
            <span aria-hidden="true" className="art:absolute art:inset-0 art:flex art:items-center art:justify-center art:font-semibold art:text-9xl art:leading-tight art:tracking-[-0.1em] art:text-muted-foreground" style={{ clipPath: "inset(28% 0px 58%)" }}>
              {"404"}
            </span>
            <span aria-hidden="true" className="art:absolute art:inset-0 art:flex art:items-center art:justify-center art:font-semibold art:text-9xl art:leading-tight art:tracking-[-0.1em] art:text-foreground" style={{ clipPath: "inset(42% 0px 44%)" }}>
              {"404"}
            </span>
            <span aria-hidden="true" className="art:absolute art:inset-0 art:flex art:items-center art:justify-center art:font-semibold art:text-9xl art:leading-tight art:tracking-[-0.1em] art:text-foreground" style={{ clipPath: "inset(56% 0px 30%)" }}>
              {"404"}
            </span>
            <span aria-hidden="true" className="art:absolute art:inset-0 art:flex art:items-center art:justify-center art:font-semibold art:text-9xl art:leading-tight art:tracking-[-0.1em] art:text-muted-foreground" style={{ clipPath: "inset(70% 0px 16%)" }}>
              {"404"}
            </span>
            <span aria-hidden="true" className="art:absolute art:inset-0 art:flex art:items-center art:justify-center art:font-semibold art:text-9xl art:leading-tight art:tracking-[-0.1em] art:text-foreground" style={{ clipPath: "inset(84% 0px 0%)" }}>
              {"404"}
