            {"Lost the thread."}
          </h1>
          <motion.a {...press} className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:gap-2 art:px-6 art:text-base art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:mt-5 art:bg-primary art:text-primary-foreground art:hover:bg-primary/85 art:h-9 art:rounded-full" href="/" tabIndex={0}>
